CREATE proc [dbo].[uspGetOpenInventory] @Sid as int as Select i.ItemId,i.Item,u.Unit,u.UId,(Select isnull(Sum(Qty),0) from WareHouse_Store where [Type]='In' and ItemId=i.ItemId and SId=@Sid and  OpenInvId > 0) as OpenBalance,isnull([dbo].uspGetItemAvgRateFunc(@Sid,i.ItemId,null,null,0),0) as RatePerPcs, cast(0 as decimal(18,2)) as Amount, isnull((Select distinct(OpenInvId) from WareHouse_Store where OpenInvId > 0 and  OpenInvId = (select max(OpenInvId) from WareHouse_Store)),0) as OpenInvId From Item i inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit u on iu.PurUnit=u.Uid inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId where  sc.SubCategory<>'Sub Recipe' order by i.Item